// Face and palm exclusion only. No identity inference, recording or uploads.
export function decodeFaces(outputs,size=320,threshold=.8){const boxes=[];for(const stride of [8,16,32]){const cls=outputs['cls_'+stride]?.data,obj=outputs['obj_'+stride]?.data,reg=outputs['bbox_'+stride]?.data;if(!cls||!obj||!reg)continue;const grid=size/stride;for(let i=0;i<cls.length;i++){const score=Math.sqrt(Math.max(0,cls[i]*obj[i]));if(score<threshold)continue;const cx=(i%grid+reg[i*4])*stride/size,cy=(Math.floor(i/grid)+reg[i*4+1])*stride/size,w=Math.exp(reg[i*4+2])*stride/size,h=Math.exp(reg[i*4+3])*stride/size;if(w*h>=.002)boxes.push({score,bbox:[cx-w/2,cy-h/2,w,h]});}}return suppress(boxes);}
export function decodePalms(scores,reg,threshold=.6){const boxes=[];for(let i=0;i<scores.length;i++){const score=1/(1+Math.exp(-scores[i]));if(score<threshold)continue;const grid=i<1152?24:12,local=i<1152?Math.floor(i/2):Math.floor((i-1152)/6),ax=(local%grid+.5)/grid,ay=(Math.floor(local/grid)+.5)/grid,cx=ax+reg[i*18]/192,cy=ay+reg[i*18+1]/192,w=reg[i*18+2]/192,h=reg[i*18+3]/192;if(w>0&&h>0&&w*h>=.008)boxes.push({score,bbox:[cx-w/2,cy-h/2,w,h]});}return suppress(boxes);}
function suppress(boxes){const kept=[];for(const box of boxes.sort((a,b)=>b.score-a.score)){if(kept.some(other=>{const a=box.bbox,b=other.bbox,w=Math.max(0,Math.min(a[0]+a[2],b[0]+b[2])-Math.max(a[0],b[0])),h=Math.max(0,Math.min(a[1]+a[3],b[1]+b[3])-Math.max(a[1],b[1]));return w*h/(a[2]*a[3]+b[2]*b[3]-w*h)>.3;}))continue;kept.push(box);if(kept.length===8)break;}return kept;}
export async function createHumanGuard(ort){
 const metadata=await(await fetch('/dlc-human-guard.json',{cache:'no-cache'})).json();
 const sessions=await Promise.all(metadata.models.map(async model=>{const response=await fetch('/'+model.file+'?sha='+model.sha256);if(!response.ok)throw Error('Human exclusion model unavailable.');const bytes=await response.arrayBuffer(),sha=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(sha!==model.sha256)throw Error('Human exclusion model integrity check failed.');return ort.InferenceSession.create(bytes,{executionProviders:['wasm'],graphOptimizationLevel:'all'});}));
 const palm=sessions[metadata.models.findIndex(x=>x.file==='dlc-palm.onnx')],face=sessions[metadata.models.findIndex(x=>x.file==='dlc-face.onnx')];
 const source=new OffscreenCanvas(224,224),src=source.getContext('2d'),canvas=new OffscreenCanvas(320,320),ctx=canvas.getContext('2d',{willReadFrequently:true});
 async function run(session,array,shape){const tensor=new ort.Tensor('float32',array,shape);try{return await session.run({[session.inputNames[0]]:tensor});}finally{tensor.dispose();}}
 return {async detect(pixels){src.putImageData(new ImageData(pixels,224,224),0,0);ctx.drawImage(source,0,0,320,320);const big=ctx.getImageData(0,0,320,320).data,bgr=new Float32Array(3*320*320);for(let i=0;i<320*320;i++)for(let c=0;c<3;c++)bgr[c*320*320+i]=big[i*4+2-c];ctx.drawImage(source,0,0,192,192);const small=ctx.getImageData(0,0,192,192).data,rgb=new Float32Array(192*192*3);for(let i=0;i<192*192;i++)for(let c=0;c<3;c++)rgb[i*3+c]=small[i*4+c]/255;
  let a,b;try{a=await run(face,bgr,[1,3,320,320]);b=await run(palm,rgb,[1,192,192,3]);return {faces:decodeFaces(a),palms:decodePalms(b.Identity_1.data,b.Identity.data)};}finally{if(a)for(const value of Object.values(a))value.dispose();if(b)for(const value of Object.values(b))value.dispose();}
 }};
}
